-- ═══════════════════════════════════════════════════════════════════════════
--  Venoxa Level Test — schema migration
--
--  Run ONCE in Supabase Dashboard → SQL Editor → New query.
--  This file is written for the Supabase Postgres instance that already has
--  public.users (see artifacts/venoxa/supabase-schema.sql).
--
--  It does NOT seed items. After running this, run migrations/level-test-seed.sql
--  (generated by scripts/level-test-generate-items.ts), then have a teacher
--  review the items before activating them.
--
--  Security model
--  --------------
--  The level-test API connects with DATABASE_URL (a Postgres role that
--  bypasses RLS) and is the only reader/writer. RLS is enabled with no
--  policies so the anon/authenticated Supabase clients cannot read items,
--  correct answers, sessions, responses, or results directly.
--  The public verify endpoint is served by the API, which returns only
--  name/level/score/date/valid.
-- ═══════════════════════════════════════════════════════════════════════════

create extension if not exists pgcrypto;

-- ── Reading passages ───────────────────────────────────────────────────────
create table if not exists public.lt_passages (
  id          text primary key,
  cefr_tag    text not null check (cefr_tag in ('A1','A2','B1','B2','C1','C2')),
  title       text not null default '',
  body        text not null,
  word_count  integer not null check (word_count > 0),
  created_at  timestamptz not null default now()
);

-- ── Item bank ──────────────────────────────────────────────────────────────
create table if not exists public.lt_items (
  id             text primary key,
  type           text not null check (type in ('grammar','vocab','reading','listening')),
  cefr_tag       text not null check (cefr_tag in ('A1','A2','B1','B2','C1','C2')),
  difficulty_b   double precision not null,
  stem           text not null,
  options        jsonb not null check (jsonb_typeof(options) = 'array' and jsonb_array_length(options) = 4),
  correct_index  integer not null check (correct_index between 0 and 3),
  passage_id     text references public.lt_passages(id) on delete set null,
  passage_order  integer check (passage_order is null or passage_order > 0),
  audio_script   text,
  audio_url      text,
  source         text not null default 'ai',
  reviewed       boolean not null default false,
  times_shown    integer not null default 0,
  times_correct  integer not null default 0,
  status         text not null default 'draft' check (status in ('draft','active','retired')),
  created_at     timestamptz not null default now(),
  -- Reading items must belong to a passage; other types must not.
  constraint lt_items_passage_shape check (
    (type = 'reading' and passage_id is not null) or
    (type <> 'reading' and passage_id is null)
  ),
  -- Listening items need a script; other types must not have one.
  constraint lt_items_audio_shape check (
    (type = 'listening' and audio_script is not null) or
    (type <> 'listening' and audio_script is null)
  )
);

create index if not exists lt_items_active_pool_idx
  on public.lt_items (status, type, cefr_tag)
  where status = 'active';
create index if not exists lt_items_passage_idx
  on public.lt_items (passage_id, id)
  where passage_id is not null;

-- ── Cached listening audio ─────────────────────────────────────────────────
-- Audio is generated once by scripts/level-test-cache-audio.ts and streamed
-- by the API through short-lived signed URLs. Storing bytes in Postgres keeps
-- the cache identical in local dev and on Vercel.
create table if not exists public.lt_audio (
  item_id       text primary key references public.lt_items(id) on delete cascade,
  content_type  text not null default 'audio/mpeg',
  bytes         bytea not null,
  duration_ms   integer,
  created_at    timestamptz not null default now()
);

-- ── Sessions ───────────────────────────────────────────────────────────────
create table if not exists public.lt_sessions (
  id                uuid primary key default gen_random_uuid(),
  user_id           uuid not null references public.users(id) on delete cascade,
  mode              text not null default 'standard' check (mode in ('standard','quick')),
  status            text not null default 'active' check (status in ('active','completed','expired')),
  theta             double precision not null default 0,
  se                double precision not null default 1.5,
  answered_ids      jsonb not null default '[]'::jsonb,
  counts            jsonb not null default '{}'::jsonb,
  active_passage_id text references public.lt_passages(id) on delete set null,
  option_orders     jsonb not null default '{}'::jsonb,
  current_item_id   text references public.lt_items(id),
  cert_name         text,
  started_at        timestamptz not null default now(),
  deadline          timestamptz not null,
  completed_at      timestamptz,
  last_answer_at    timestamptz,
  created_at        timestamptz not null default now()
);

create index if not exists lt_sessions_user_idx
  on public.lt_sessions (user_id, started_at desc);
create index if not exists lt_sessions_active_idx
  on public.lt_sessions (status, deadline)
  where status = 'active';

-- ── Responses ──────────────────────────────────────────────────────────────
create table if not exists public.lt_responses (
  id            bigserial primary key,
  session_id    uuid not null references public.lt_sessions(id) on delete cascade,
  item_id       text not null references public.lt_items(id),
  choice_index  integer not null check (choice_index between 0 and 3),
  correct       boolean not null,
  time_ms       integer not null check (time_ms >= 0),
  answered_at   timestamptz not null default now(),
  unique (session_id, item_id)
);

create index if not exists lt_responses_session_idx
  on public.lt_responses (session_id);
create index if not exists lt_responses_item_idx
  on public.lt_responses (item_id);

-- ── Results / certificates ─────────────────────────────────────────────────
create table if not exists public.lt_results (
  session_id     uuid primary key references public.lt_sessions(id) on delete cascade,
  cert_id        text not null unique,
  user_id        uuid not null references public.users(id) on delete cascade,
  name           text not null,
  level          text not null check (level in ('A1','A2','B1','B2','C1','C2')),
  score          integer not null check (score between 0 and 100),
  ci_low         integer not null check (ci_low between 0 and 100),
  ci_high        integer not null check (ci_high between 0 and 100),
  theta          double precision not null,
  se             double precision not null,
  section_scores jsonb not null default '{}'::jsonb,
  answered       integer not null,
  provisional    boolean not null default false,
  created_at     timestamptz not null default now(),
  constraint lt_results_ci_order check (ci_low <= score and score <= ci_high)
);

create index if not exists lt_results_user_idx
  on public.lt_results (user_id, created_at desc);
create index if not exists lt_results_cert_idx
  on public.lt_results (cert_id);

-- ── RLS: server-only tables ────────────────────────────────────────────────
alter table public.lt_passages  enable row level security;
alter table public.lt_items     enable row level security;
alter table public.lt_audio     enable row level security;
alter table public.lt_sessions  enable row level security;
alter table public.lt_responses enable row level security;
alter table public.lt_results   enable row level security;

-- No policies are created on purpose. The API's DATABASE_URL role bypasses
-- RLS; anon/authenticated clients get nothing. If you later add a Supabase
-- client-side admin view, add an explicit policy rather than disabling RLS.

-- ── Comments ───────────────────────────────────────────────────────────────
comment on table public.lt_items is
  'Venoxa Level Test item bank. correct_index/difficulty_b must never be sent to clients.';
comment on table public.lt_sessions is
  'Adaptive session state. One pending item per session; server owns the clock.';
comment on table public.lt_results is
  'Final scores and certificate identity. cert_id format VX-YYYY-XXXX-XXXX.';
